const meetingSourceLabels={recording:'Recording',zoom:'Zoom',meet:'Google Meet'};
let pendingMeetingSource='recording';
function meetingSourceDialog(){const box=document.getElementById('modal');box.className='recording-dialog';box.innerHTML='<div class="record-heading"><div><h2>Choose meeting source</h2><p>Record a conversation or use your preferred meeting platform.</p></div></div><div class="meeting-source-grid">'+Object.entries(meetingSourceLabels).map(([key,label])=>'<button class="meeting-source-card" onclick="meetingSetupDialog(\''+key+'\')"><span class="input-icon">'+icon(key==='recording'?'teams':'projects')+'</span><strong>'+label+'</strong><span>'+({recording:'Set up recording and bilingual transcripts.',zoom:'Set up a Zoom meeting workspace.',meet:'Set up a Google Meet workspace.'})[key]+'</span></button>').join('')+'</div><div class="form-footer"><button onclick="document.getElementById(\'modal\').close()">Cancel</button></div>';if(!box.open)box.showModal();}
function meetingSetupDialog(type){pendingMeetingSource=type;const d=selected?requestDraft():{},saved=d.sourceSettings?.[type]||{},box=document.getElementById('modal');box.innerHTML='<form onsubmit="submitMeetingSetup(event)"><div class="record-heading"><div><h2>'+meetingSourceLabels[type]+' setup</h2><p>Configure your session before opening the transcript workspace.</p></div></div><div class="form"><label class="field">Session name<input name="title" required value="'+esc(saved.title||'Product requirements discussion')+'"></label>'+(type==='recording'?'<label class="field">Audio source<select name="audio"><option>Microphone</option><option>Shared tab audio</option></select></label>':'<label class="field">Demo meeting link<input name="link" type="text" value="'+esc(saved.link||(type==='zoom'?'https://zoom.us/j/12345678901':'https://meet.google.com/abc-defg-hij'))+'" placeholder="'+(type==='zoom'?'https://zoom.us/j/12345678901':'https://meet.google.com/abc-defg-hij')+'"></label>')+'<label class="field">Translation<select name="language"><option value="en-ja">English → 日本語</option><option value="ja-en">日本語 → English</option></select></label><p class="sub">Demo mode: sample links open the UI preview only. No real meeting is joined. Speakers and transcripts are simulated.</p><p id="meetingSetupError" role="alert"></p></div><div class="form-footer"><button type="button" onclick="meetingSourceDialog()">‹ Back</button><button class="primary">Start preview →</button></div></form>';if(saved.language)box.querySelector('[name=language]').value=saved.language;if(saved.audio&&type==='recording')box.querySelector('[name=audio]').value=saved.audio;}
function submitMeetingSetup(e){e.preventDefault();if(!selected){document.getElementById('meetingSetupError').textContent='Select a project first.';return;}const f=Object.fromEntries(new FormData(e.target)),type=pendingMeetingSource;if(type!=='recording'&&!f.link.trim())f.link=type==='zoom'?'https://zoom.us/j/12345678901':'https://meet.google.com/abc-defg-hij';const d=requestDraft();d.sourceSettings ||= {};d.sourceSettings[type]=f;d.meetingType=type;d.title=f.title;d.link=f.link||'';d.tab='meeting';document.getElementById('modal').close();if(screen!=='request')navigate('request');startContextMeeting();}
recordingDialog=meetingSourceDialog;
setupContextMeeting=meetingSourceDialog;
contextMeeting=function(){const d=requestDraft(),type=d.meetingType==='google'?'zoom':d.meetingType;return '<div class="context-meeting-actions"><div><span class="badge blue">'+(meetingSourceLabels[type]||'Recording')+'</span><h2>'+esc(d.title||'Product requirements discussion')+'</h2></div>'+button('Set up meeting or recording','meetingSourceDialog()')+'<button class="request-stop" '+(d.running?'':'disabled')+' onclick="stopContextMeeting()">■ '+(type==='recording'?'Stop recording':'Stop meeting')+'</button></div><div class="notice">'+(d.running?'Sample playback in progress':'Ready · Your transcript is kept')+' · Demo only. No live audio is captured.</div>'+contextTranscripts(d);};
const meetingTabBeforePopup=contextTab;contextTab=function(tab){meetingTabBeforePopup(tab);if(tab==='meeting'&&!requestDraft().sourceSettings)meetingSourceDialog();};
Object.assign(localizedLabels,{'Choose meeting source':'会議ソースを選択','Recording':'録音','Google Meet':'Google Meet','Zoom':'Zoom','Recording setup':'録音設定','Zoom setup':'Zoom の設定','Google Meet setup':'Google Meet の設定','Session name':'セッション名','Audio source':'音声ソース','Microphone':'マイク','Shared tab audio':'共有タブの音声','Meeting link':'会議リンク','Demo meeting link':'デモ会議リンク','Translation':'翻訳','Set up meeting or recording':'会議・録音を設定','Start preview →':'プレビューを開始 →','‹ Back':'‹ 戻る'});
render();
const recordingOnlyContextUI=contextMeeting;
function toggleMeetingDemoControl(key){const d=requestDraft();d[key]=!d[key];render();}
contextMeeting=function(){const d=requestDraft(),type=d.meetingType==='google'?'zoom':d.meetingType;if(type==='recording')return recordingOnlyContextUI();const label=meetingSourceLabels[type]||'Zoom';return '<div class="context-meeting-actions"><div><span class="badge blue">'+label+'</span><h2>'+esc(d.title||'Product requirements discussion')+'</h2><small>'+esc(d.sourceSettings?.[type]?.link||d.link||'Demo meeting')+'</small></div>'+button('Meeting setup','meetingSourceDialog()')+'</div><div class="provider-meeting-layout"><section class="meeting-video panel"><div class="panel-title"><h3>'+label+' · Meeting preview</h3><span class="badge '+(d.running?'blue':'gray')+'">'+(d.running?'Sample playback':'Preview stopped')+'</span></div><div class="participant-grid">'+[['SC','Sahim Chy','indigo'],['MC','Maya Chen','blue'],['AM','Alex Morgan','teal'],['You','You','slate']].map(([initial,name,color],i)=>'<div class="participant '+color+'"><span class="participant-avatar">'+initial+'</span><small>'+name+' · '+(i===3&&d.demoMuted?'Muted': 'Demo participant')+'</small>'+(i===3&&d.demoCameraOff?'<span class="badge gray">Camera off</span>':'')+'</div>').join('')+'</div>'+(d.demoSharing?'<div class="notice">Screen sharing preview · No screen is being captured.</div>':'')+'<div class="call-controls"><button aria-pressed="'+!!d.demoMuted+'" onclick="toggleMeetingDemoControl(\'demoMuted\')">'+(d.demoMuted?'Unmute':'Mute')+'</button><button aria-pressed="'+!!d.demoCameraOff+'" onclick="toggleMeetingDemoControl(\'demoCameraOff\')">'+(d.demoCameraOff?'Camera on':'Camera off')+'</button><button aria-pressed="'+!!d.demoSharing+'" onclick="toggleMeetingDemoControl(\'demoSharing\')">'+(d.demoSharing?'Stop sharing':'Share screen')+'</button>'+(d.running?'<button class="request-stop" onclick="stopContextMeeting()">■ Stop meeting</button>':button('▶ Replay demo','startContextMeeting()',true))+'</div><p class="meeting-disclaimer">Demo meeting interface. Controls simulate local UI states; no real meeting, audio, video or screen capture is connected.</p></section><section class="provider-transcripts"><div class="panel-title"><h3>Transcript & translation</h3></div>'+contextTranscripts(d)+'</section></div>';};
Object.assign(localizedLabels,{'Meeting setup':'会議の設定','Meeting preview':'会議プレビュー','Preview stopped':'プレビュー停止','Mute':'ミュート','Unmute':'ミュート解除','Camera on':'カメラをオン','Camera off':'カメラをオフ','Share screen':'画面共有','Stop sharing':'共有を停止','▶ Replay demo':'▶ デモを再生'});
render();
contextTranscripts=function(d){const type=d.meetingType==='google'?'zoom':d.meetingType,jaFirst=d.sourceSettings?.[type]?.language==='ja-en',source=jaFirst?2:1,target=jaFirst?1:2;return '<section class="paired-transcripts" aria-label="Transcript and translation"><div class="paired-language-head"><div><small>Transcript</small><strong>'+ (jaFirst?'日本語':'English')+'</strong></div><div><small>Translation</small><strong>'+(jaFirst?'English':'日本語')+'</strong></div></div><div class="paired-transcript-scroll" tabindex="0" aria-label="Bilingual transcript">'+(d.entries.length?d.entries.map((row,i)=>'<article class="paired-transcript-row">'+[source,target].map((col,j)=>'<div class="paired-transcript-cell" lang="'+(col===1?'en':'ja')+'"><header><span class="paired-speaker"><span class="paired-avatar">'+esc(row[0].slice(0,1))+'</span>'+esc(row[0])+'</span><time>'+String(Math.floor(i*8/60)).padStart(2,'0')+':'+String(i*8%60).padStart(2,'0')+'</time></header><p>'+esc(row[col])+'</p></div>').join('')+'</article>').join(''):'<div class="paired-empty">Transcript and translation will appear here when the preview starts.</div>')+'</div><footer>'+d.entries.length+' entries · '+(d.running?'Sample playback':'Transcript saved in this session')+'</footer></section>';};
render();
